package api

import (
	"bytes"
	"crypto/sha256"
	"io"
	"net/http"
	"sync"
	"time"

	"example.com/tally/internal/auth"
)

// Idempotency-Key support for POST /v1/invoices/{id}/pay. The first request with a key runs and its response is kept for
// 24 hours. A later request with the same key, organization, invoice and body gets that response again. A response with a
// status of 500 or more is not kept, so a retry runs again. Records are held in memory and are lost on restart.

const (
	idempotencyHeader = "Idempotency-Key"
	idempotencyTTL    = 24 * time.Hour
)

// idempotencyStore holds the records of all organizations. It is safe for concurrent use.
type idempotencyStore struct {
	mu      sync.Mutex
	records map[idempotencyScope]*idempotencyRecord
}

// idempotencyScope is a key within an organization: two organizations may use the same key.
type idempotencyScope struct{ orgID, key string }

// idempotencyRecord is what the first request with a key left behind.
type idempotencyRecord struct {
	invoiceID string
	bodyHash  [sha256.Size]byte
	done      bool
	doneAt    time.Time
	status    int
	header    http.Header
	body      []byte
}

type claimOutcome int

const (
	claimNew        claimOutcome = iota // no record: the caller runs the request
	claimReplay                         // a kept response: the caller replays it
	claimReused                         // the key was used for another invoice or body
	claimInProgress                     // the first request with the key has not finished
)

// claim looks up the record for scope, or creates an in-progress one. Expired records are dropped first.
func (st *idempotencyStore) claim(scope idempotencyScope, invoiceID string, bodyHash [sha256.Size]byte, now time.Time) (*idempotencyRecord, claimOutcome) {
	st.mu.Lock()
	defer st.mu.Unlock()
	for k, rec := range st.records {
		if rec.done && !now.Before(rec.doneAt.Add(idempotencyTTL)) {
			delete(st.records, k)
		}
	}
	if rec, ok := st.records[scope]; ok {
		switch {
		case rec.invoiceID != invoiceID || rec.bodyHash != bodyHash:
			return nil, claimReused
		case !rec.done:
			return nil, claimInProgress
		default:
			return rec, claimReplay
		}
	}
	if st.records == nil {
		st.records = map[idempotencyScope]*idempotencyRecord{}
	}
	rec := &idempotencyRecord{invoiceID: invoiceID, bodyHash: bodyHash}
	st.records[scope] = rec
	return rec, claimNew
}

// keep stores the response of rec for replay, or drops rec when the status is 500 or more.
func (st *idempotencyStore) keep(scope idempotencyScope, rec *idempotencyRecord, c *captured, now time.Time) {
	if c.status >= http.StatusInternalServerError {
		st.forget(scope, rec)
		return
	}
	st.mu.Lock()
	defer st.mu.Unlock()
	rec.done, rec.doneAt = true, now
	rec.status, rec.header, rec.body = c.status, c.header.Clone(), c.body.Bytes()
}

// forget drops rec, so that a retry with the same key runs again.
func (st *idempotencyStore) forget(scope idempotencyScope, rec *idempotencyRecord) {
	st.mu.Lock()
	defer st.mu.Unlock()
	if st.records[scope] == rec {
		delete(st.records, scope)
	}
}

// captured is a response a handler wrote, held back until the handler returns.
type captured struct {
	header http.Header
	status int
	body   bytes.Buffer
}

func (c *captured) Header() http.Header { return c.header }

func (c *captured) WriteHeader(status int) {
	if c.status == 0 {
		c.status = status
	}
}

func (c *captured) Write(b []byte) (int, error) {
	if c.status == 0 {
		c.status = http.StatusOK
	}
	return c.body.Write(b)
}

// validIdempotencyKey reports whether key is 1 to 255 printable ASCII characters.
func validIdempotencyKey(key string) bool {
	if len(key) < 1 || len(key) > 255 {
		return false
	}
	for i := 0; i < len(key); i++ {
		if key[i] < 0x20 || key[i] > 0x7e {
			return false
		}
	}
	return true
}

// idempotent runs h with the request's Idempotency-Key, if it has one. Without a key, h runs as it is.
func (s *Server) idempotent(h handler) handler {
	return func(w http.ResponseWriter, r *http.Request, p auth.Principal) {
		keys := r.Header.Values(idempotencyHeader)
		if len(keys) == 0 {
			h(w, r, p)
			return
		}
		if len(keys) > 1 || !validIdempotencyKey(keys[0]) {
			writeError(w, http.StatusBadRequest, "invalid_idempotency_key", "Idempotency-Key is 1 to 255 printable ASCII characters")
			return
		}
		scope := idempotencyScope{orgID: p.OrgID, key: keys[0]}
		// The body is read once, so that its hash can be compared and the handler can still decode it.
		body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
		if err != nil {
			writeError(w, http.StatusBadRequest, "invalid_body", "the body could not be read: "+err.Error())
			return
		}
		r.Body = io.NopCloser(bytes.NewReader(body))
		now := s.clock.Now()
		rec, outcome := s.idem.claim(scope, r.PathValue("id"), sha256.Sum256(body), now)
		switch outcome {
		case claimReused:
			writeError(w, http.StatusUnprocessableEntity, "idempotency_key_reused", "this Idempotency-Key was used for another invoice or request body")
			return
		case claimInProgress:
			writeError(w, http.StatusConflict, "request_in_progress", "a request with this Idempotency-Key is still being handled; retry later")
			return
		case claimReplay:
			replay(w, rec)
			return
		}
		// A panic leaves no response to keep, so the record is dropped and the panic goes on to recoverPanics.
		kept := false
		defer func() {
			if !kept {
				s.idem.forget(scope, rec)
			}
		}()
		c := &captured{header: http.Header{}}
		h(c, r, p)
		kept = true
		s.idem.keep(scope, rec, c, now)
		copyHeader(w, c.header)
		w.WriteHeader(c.status)
		_, _ = w.Write(c.body.Bytes())
	}
}

// replay answers with a kept response, marked as a replay.
func replay(w http.ResponseWriter, rec *idempotencyRecord) {
	copyHeader(w, rec.header)
	w.Header().Set("Idempotent-Replayed", "true")
	w.WriteHeader(rec.status)
	_, _ = w.Write(rec.body)
}

func copyHeader(w http.ResponseWriter, h http.Header) {
	for k, vs := range h {
		w.Header()[k] = append([]string(nil), vs...)
	}
}

