	}
	return c.body.Write(b)
}

// validIdempotencyKey reports whether key is 1 to 255 printable ASCII characters.
func validIdempotencyKey(key string) bool {
	if len(key) < 1 || len(key) > 255 {
		return false
	}
	for i := 0; i < len(key); i++ {
		if key[i] < 0x20 || key[i] > 0x7e {
			return false
		}
	}
	return true
}

// idempotent runs h with the request's Idempotency-Key, if it has one. Without a key, h runs as it is.
func (s *Server) idempotent(h handler) handler {
	return func(w http.ResponseWriter, r *http.Request, p auth.Principal) {
		keys := r.Header.Values(idempotencyHeader)
		if len(keys) == 0 {
			h(w, r, p)
			return
		}
		if len(keys) > 1 || !validIdempotencyKey(keys[0]) {
			writeError(w, http.StatusBadRequest, "invalid_idempotency_key", "Idempotency-Key is 1 to 255 printable ASCII characters")
			return
		}
		scope := idempotencyScope{orgID: p.OrgID, key: keys[0]}
		// The body is read once, so that its hash can be compared and the handler can still decode it.
		body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
		if err != nil {
			writeError(w, http.StatusBadRequest, "invalid_body", "the body could not be read: "+err.Error())
			return
		}
		r.Body = io.NopCloser(bytes.NewReader(body))
		now := s.clock.Now()
		rec, outcome := s.idem.claim(scope, r.PathValue("id"), sha256.Sum256(body), now)
		switch outcome {
		case claimReused:
			writeError(w, http.StatusUnprocessableEntity, "idempotency_key_reused", "this Idempotency-Key was used for another invoice or request body")
			return
		case claimInProgress:
			writeError(w, http.StatusConflict, "request_in_progress", "a request with this Idempotency-Key is still being handled; retry later")
			return
		case claimReplay:
			replay(w, rec)
			return
		}
		// A panic leaves no response to keep, so the record is dropped and the panic goes on to recoverPanics.
		kept := false
		defer func() {
			if !kept {
				s.idem.forget(scope, rec)
			}
		}()
		c := &captured{header: http.Header{}}
		h(c, r, p)
		kept = true
		s.idem.keep(scope, rec, c, now)
