// openInvoice creates an open invoice for a customer of org and returns its ID.
func openInvoice(t *testing.T, e *apitest.Env, org apitest.Org, customerID string) string {
	t.Helper()
	var inv store.Invoice
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", org.Key, map[string]any{
		"customer_id": customerID, "currency": "USD", "lines": []store.Line{{Description: "Work", Quantity: 1, UnitAmount: 1000}},
	}, &inv)
	return inv.ID
}

// payWithKeys pays an invoice with the given Idempotency-Key header values.
func payWithKeys(e *apitest.Env, org apitest.Org, invoiceID, method string, keys ...string) *apitest.Response {
	return e.DoWith("POST", "/v1/invoices/"+invoiceID+"/pay", org.Key, map[string]string{"payment_method": method}, http.Header{"Idempotency-Key": keys})
}

func TestPayIdempotencyKeyIsValidated(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	inv := openInvoice(t, e, e.Acme, c.ID)
	for _, key := range []string{"", strings.Repeat("k", 256), "tab\tkey", "naïve"} {
		if r := payWithKeys(e, e.Acme, inv, "pm_card_visa", key); r.Code != http.StatusBadRequest || r.Map(t)["error"] != "invalid_idempotency_key" {
			t.Fatalf("key %q: %s", key, r)
		}
	}
	if r := payWithKeys(e, e.Acme, inv, "pm_card_visa", "k", "k"); r.Code != http.StatusBadRequest || r.Map(t)["error"] != "invalid_idempotency_key" {
		t.Fatalf("two keys: %s", r)
	}
	if n := len(e.Gateway.Calls()); n != 0 {
		t.Fatalf("%d charges were attempted with invalid keys", n)
	}
	if r := payWithKeys(e, e.Acme, inv, "pm_card_declined", strings.Repeat("k", 255)); r.Code != http.StatusPaymentRequired {
		t.Fatalf("a 255-character key: %s", r)
	}
}

func TestPayIdempotentReplay(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	inv := openInvoice(t, e, e.Acme, c.ID)
	first := payWithKeys(e, e.Acme, inv, "pm_card_visa", "order-1")
	if first.Code != http.StatusOK || first.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("first: %s", first)
	}
	again := payWithKeys(e, e.Acme, inv, "pm_card_visa", "order-1")
	if again.Code != first.Code || !bytes.Equal(again.Body, first.Body) || again.Header.Get("Idempotent-Replayed") != "true" {
		t.Fatalf("retry: %s (replayed %q), want %s", again, again.Header.Get("Idempotent-Replayed"), first)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("%d charges, want 1", n)
	}
}

