func TestPayIdempotencyRequestInProgress(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	inv := openInvoice(t, e, e.Acme, c.ID)
	started, release := make(chan struct{}, 1), make(chan struct{})
	e.Gateway.OnCharge = func(payments.ChargeRequest) {
		started <- struct{}{}
		<-release
	}
	first := make(chan *apitest.Response, 1)
	go func() { first <- payWithKeys(e, e.Acme, inv, "pm_card_visa", "slow") }()
	<-started
	if r := payWithKeys(e, e.Acme, inv, "pm_card_visa", "slow"); r.Code != http.StatusConflict || r.Map(t)["error"] != "request_in_progress" {
		t.Fatalf("while the first is handled: %s", r)
	}
