		t.Fatalf("after the first finished: %s", r)
	}
}

func TestPayIdempotencyKeepsAnswersUnder500Only(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	inv := openInvoice(t, e, e.Acme, c.ID)

	declined := payWithKeys(e, e.Acme, inv, "pm_card_declined", "declined")
	if declined.Code != http.StatusPaymentRequired {
		t.Fatalf("declined: %s", declined)
	}
	if r := payWithKeys(e, e.Acme, inv, "pm_card_declined", "declined"); r.Code != declined.Code || !bytes.Equal(r.Body, declined.Body) || r.Header.Get("Idempotent-Replayed") != "true" {
		t.Fatalf("declined retry: %s", r)
	}

	// 503 is not kept: the retry runs the charge again.
	for i := 0; i < 2; i++ {
		if r := payWithKeys(e, e.Acme, inv, "pm_gateway_down", "down"); r.Code != http.StatusServiceUnavailable || r.Header.Get("Idempotent-Replayed") != "" {
			t.Fatalf("gateway down, attempt %d: %s", i+1, r)
		}
	}
	if n := len(e.Gateway.Calls()); n != 3 {
		t.Fatalf("%d gateway calls, want 3 (1 decline, 2 outages)", n)
	}

	if r := payWithKeys(e, e.Acme, inv, "pm_card_visa", "paid"); r.Code != http.StatusOK {
		t.Fatalf("paid: %s", r)
	}
	late := payWithKeys(e, e.Acme, inv, "pm_card_visa", "late")
	if late.Code != http.StatusConflict || late.Map(t)["error"] != "already_paid" {
		t.Fatalf("already paid: %s", late)
	}
	if r := payWithKeys(e, e.Acme, inv, "pm_card_visa", "late"); r.Code != late.Code || !bytes.Equal(r.Body, late.Body) || r.Header.Get("Idempotent-Replayed") != "true" {
		t.Fatalf("already paid retry: %s", r)
	}
}

func TestPayIdempotencyKeyExpiresAfter24Hours(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	inv := openInvoice(t, e, e.Acme, c.ID)
	if r := payWithKeys(e, e.Acme, inv, "pm_card_declined", "old"); r.Code != http.StatusPaymentRequired {
		t.Fatalf("first: %s", r)
	}
	e.Clock.Advance(23 * time.Hour)
	if r := payWithKeys(e, e.Acme, inv, "pm_card_declined", "old"); r.Header.Get("Idempotent-Replayed") != "true" {
		t.Fatalf("after 23 hours: %s", r)
	}
	e.Clock.Advance(time.Hour)
	if r := payWithKeys(e, e.Acme, inv, "pm_card_declined", "old"); r.Code != http.StatusPaymentRequired || r.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("after 24 hours the key is new: %s", r)
	}
	if n := len(e.Gateway.Calls()); n != 2 {
		t.Fatalf("%d gateway calls, want 2", n)
	}
}

func TestPayTwoRequestsNeverBothCharge(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	inv := openInvoice(t, e, e.Acme, c.ID)
	started, release := make(chan struct{}, 1), make(chan struct{})
	e.Gateway.OnCharge = func(payments.ChargeRequest) {
		started <- struct{}{}
		<-release
	}
	first := make(chan *apitest.Response, 1)
	go func() {
		first <- e.Do("POST", "/v1/invoices/"+inv+"/pay", e.Acme.Key, map[string]string{"payment_method": "pm_card_visa"})
	}()
	<-started
	if r := e.Do("POST", "/v1/invoices/"+inv+"/pay", e.Acme.Key, map[string]string{"payment_method": "pm_card_visa"}); r.Code != http.StatusConflict || r.Map(t)["error"] != "payment_in_progress" {
		t.Fatalf("second pay without a key: %s", r)
	}
	if r := payWithKeys(e, e.Acme, inv, "pm_card_visa", "other"); r.Code != http.StatusConflict || r.Map(t)["error"] != "payment_in_progress" {
		t.Fatalf("second pay with another key: %s", r)
	}
	close(release)
	if r := <-first; r.Code != http.StatusOK {
		t.Fatalf("first: %s", r)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("%d charges, want 1", n)
	}
}

