	if r := payWithKeys(e, e.Acme, inv, "pm_card_declined", "old"); r.Code != http.StatusPaymentRequired || r.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("after 24 hours the key is new: %s", r)
	}
	if n := len(e.Gateway.Calls()); n != 2 {
		t.Fatalf("%d gateway calls, want 2", n)
	}
}

func TestPayTwoRequestsNeverBothCharge(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	inv := openInvoice(t, e, e.Acme, c.ID)
	started, release := make(chan struct{}, 1), make(chan struct{})
	e.Gateway.OnCharge = func(payments.ChargeRequest) {
		started <- struct{}{}
		<-release
	}
	first := make(chan *apitest.Response, 1)
	go func() {
		first <- e.Do("POST", "/v1/invoices/"+inv+"/pay", e.Acme.Key, map[string]string{"payment_method": "pm_card_visa"})
	}()
	<-started
	if r := e.Do("POST", "/v1/invoices/"+inv+"/pay", e.Acme.Key, map[string]string{"payment_method": "pm_card_visa"}); r.Code != http.StatusConflict || r.Map(t)["error"] != "payment_in_progress" {
		t.Fatalf("second pay without a key: %s", r)
	}
	if r := payWithKeys(e, e.Acme, inv, "pm_card_visa", "other"); r.Code != http.StatusConflict || r.Map(t)["error"] != "payment_in_progress" {
		t.Fatalf("second pay with another key: %s", r)
	}
	close(release)
	if r := <-first; r.Code != http.StatusOK {
		t.Fatalf("first: %s", r)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("%d charges, want 1", n)
	}
}

